all.css:
.pageBackground {
  --roseHot: #ff2d55;
  --roseCore: #ffd9e0;
  --roseMid: #7a0f1f;
  --roseDeep: #0d0308;
  overflow: hidden;
}

.rubyScene {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(120% 80% at 50% 118%, color-mix(in srgb, var(--roseMid) 55%, transparent) 0%, transparent 62%),
    linear-gradient(to top, color-mix(in srgb, var(--roseDeep) 78%, transparent) 0%, transparent 58%);
}

.rubyGlow {
  position: absolute;
  inset: auto -10% -30% -10%;
  height: 70%;
  background: radial-gradient(60% 100% at 50% 100%, color-mix(in srgb, var(--roseHot) 26%, transparent) 0%, color-mix(in srgb, var(--roseMid) 20%, transparent) 45%, transparent 75%);
  filter: blur(34px);
  opacity: .6;
}

.rubyFloor {
  position: absolute;
  inset: auto 0 0 0;
  height: 16%;
  background: linear-gradient(to top, color-mix(in srgb, var(--roseMid) 40%, transparent), transparent);
  filter: blur(10px);
}

.rubyChar {
  position: absolute;
  right: 0%;
  bottom: 12px;
  width: auto;
  height: 105%;
  object-fit: contain;
  object-position: bottom right;
  opacity: .34;
  filter: drop-shadow(0 0 40px color-mix(in srgb, var(--roseHot) 30%, transparent));
  mask-image: linear-gradient(to top, transparent 0%, #000 14%, #000 100%);
  z-index: 1;
  transform-origin: 60% 100%;
  will-change: transform;
  animation: rubyWaver 17s ease-in-out infinite;
}

/* ---- Petal fields ------------------------------------------------------ */
/* Three nested elements, one job each:
   .petalField: static, clips and masks. Never animates, so the mask
                 resolves once instead of every frame.
   .petalSway: horizontal drift.
   .petalDrift: vertical fall. Separate element because both use transform. */

.petalField {
  position: absolute;
  inset: 0;
  z-index: 3;
  overflow: hidden;
  pointer-events: none;
  mask-image: linear-gradient(to bottom, transparent 0%, #000 14%, #000 90%, transparent 100%);
}

.petalSway {
  position: absolute;
  inset: 0;
  will-change: transform;
  backface-visibility: hidden;
  animation: petalSway var(--swayDur) cubic-bezier(.37, 0, .63, 1) infinite;
}

.petalDrift {
  position: absolute;
  /* Overhang by one tile top and bottom so the loop seam is always offscreen.
     Extra width absorbs the sway without exposing an edge. */
  left: calc(-1 * var(--sway-abs));
  right: calc(-1 * var(--sway-abs));
  top: calc(-1 * var(--tileH));
  height: calc(100% + (2 * var(--tileH)));
  background-repeat: repeat;
  background-size: var(--tileW) var(--tileH);
  will-change: transform;
  backface-visibility: hidden;
  transform: translate3d(0, 0, 0);
  animation: petalFall var(--fallDur) linear infinite;
}

/* Near: largest, brightest, fastest, widest sway. */
.petalField--near {
  --tileW: 300px;
  --tileH: 400px;
  --fallDur: 23s;
  --swayDur: 9s;
  --sway: 16px;
  --sway-abs: 16px;
}
.petalField--near .petalDrift {
  opacity: .85;
  background-image:
    radial-gradient(4px 6px    at  60px  70px, var(--roseHot), transparent 62%),
    radial-gradient(circle 9px at  60px  70px, color-mix(in srgb, var(--roseHot) 42%, transparent), transparent 70%),
    radial-gradient(4px 6px    at 215px 150px, var(--roseCore), transparent 62%),
    radial-gradient(circle 10px at 215px 150px, color-mix(in srgb, var(--roseCore) 34%, transparent), transparent 70%),
    radial-gradient(3px 5px    at 130px 265px, var(--roseHot), transparent 62%),
    radial-gradient(circle 8px at 130px 265px, color-mix(in srgb, var(--roseHot) 40%, transparent), transparent 70%),
    radial-gradient(4px 6px    at 265px 340px, var(--roseHot), transparent 62%),
    radial-gradient(circle 9px at 265px 340px, color-mix(in srgb, var(--roseHot) 38%, transparent), transparent 70%),
    radial-gradient(3px 5px    at  25px 200px, var(--roseCore), transparent 62%),
    radial-gradient(circle 8px at  25px 200px, color-mix(in srgb, var(--roseCore) 30%, transparent), transparent 70%);
}

/* Mid: rounder dots. Petals caught flat-on rather than edge-on. */
.petalField--mid {
  --tileW: 250px;
  --tileH: 330px;
  --fallDur: 37s;
  --swayDur: 14s;
  --sway: -11px;
  --sway-abs: 11px;
}
.petalField--mid .petalDrift {
  opacity: .6;
  background-image:
    radial-gradient(4px 4px    at  40px 110px, var(--roseHot), transparent 62%),
    radial-gradient(circle 7px at  40px 110px, color-mix(in srgb, var(--roseHot) 32%, transparent), transparent 70%),
    radial-gradient(4px 4px    at 175px  45px, var(--roseCore), transparent 62%),
    radial-gradient(circle 8px at 175px  45px, color-mix(in srgb, var(--roseCore) 26%, transparent), transparent 70%),
    radial-gradient(3px 3px    at 120px 215px, var(--roseHot), transparent 62%),
    radial-gradient(circle 6px at 120px 215px, color-mix(in srgb, var(--roseHot) 30%, transparent), transparent 70%),
    radial-gradient(4px 3px    at 225px 285px, var(--roseHot), transparent 62%),
    radial-gradient(circle 7px at 225px 285px, color-mix(in srgb, var(--roseHot) 28%, transparent), transparent 70%);
}

/* Far: smallest, dimmest, slowest, shallowest sway. */
.petalField--far {
  --tileW: 200px;
  --tileH: 270px;
  --fallDur: 53s;
  --swayDur: 21s;
  --sway: 7px;
  --sway-abs: 7px;
}
.petalField--far .petalDrift {
  opacity: .4;
  background-image:
    radial-gradient(2px 3px at  70px  35px, var(--roseHot), transparent 65%),
    radial-gradient(2px 3px at 155px 130px, var(--roseCore), transparent 65%),
    radial-gradient(2px 3px at  30px 190px, var(--roseHot), transparent 65%),
    radial-gradient(2px 3px at 120px 240px, var(--roseCore), transparent 65%),
    radial-gradient(2px 3px at 185px  80px, var(--roseHot), transparent 65%);
}

/* ---- Keyframes --------------------------------------------------------- */

@keyframes petalFall {
  from { transform: translate3d(0, 0, 0); }
  to   { transform: translate3d(0, var(--tileH), 0); }
}

/* Four keyframes, not two: an explicit midpoint at each extreme keeps the
   turnaround from reading as a snap. The bezier approximates a sine ease. */
@keyframes petalSway {
  0%   { transform: translate3d(0, 0, 0); }
  25%  { transform: translate3d(var(--sway), 0, 0); }
  50%  { transform: translate3d(0, 0, 0); }
  75%  { transform: translate3d(calc(-1 * var(--sway)), 0, 0); }
  100% { transform: translate3d(0, 0, 0); }
}

@keyframes rubyWaver {
  0%, 100% { transform: translateY(0) rotate(0deg) scale(1); opacity: .34; }
  35%      { transform: translateY(-4px) rotate(.3deg) scale(1.003); opacity: .39; }
  70%      { transform: translateY(2px) rotate(-.2deg) scale(.999); opacity: .32; }
}

@media (prefers-reduced-motion: reduce) {
  .rubyChar,
  .petalSway,
  .petalDrift { animation: none; }
}

