.pageBackground {
  --iceHot: #8fd9ff;
  --iceCore: #ffffff;
  --iceMid: #2a6fa8;
  --iceDeep: #030a12;
  overflow: hidden;
}

.weissScene {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(120% 80% at 50% 118%, color-mix(in srgb, var(--iceMid) 55%, transparent) 0%, transparent 62%),
    linear-gradient(to top, color-mix(in srgb, var(--iceDeep) 78%, transparent) 0%, transparent 58%);
}

.weissGlow {
  position: absolute;
  inset: auto -10% -30% -10%;
  height: 70%;
  background: radial-gradient(60% 100% at 50% 100%, color-mix(in srgb, var(--iceHot) 26%, transparent) 0%, color-mix(in srgb, var(--iceMid) 20%, transparent) 45%, transparent 75%);
  filter: blur(34px);
  opacity: .6;
}

.weissFloor {
  position: absolute;
  inset: auto 0 0 0;
  height: 14%;
  background: linear-gradient(to top, color-mix(in srgb, var(--iceHot) 30%, transparent), transparent);
  filter: blur(10px);
}

.weissChar {
  position: absolute;
  right: 0%;
  bottom: 12px;
  width: auto;
  height: 96%;
  object-fit: contain;
  object-position: bottom right;
  opacity: .36;
  filter: drop-shadow(0 0 40px color-mix(in srgb, var(--iceHot) 35%, transparent));
  mask-image: linear-gradient(to top, transparent 0%, #000 14%, #000 100%);
  z-index: 1;
  transform-origin: 60% 100%;
  animation: weissSway 15s ease-in-out infinite;
}

/* Summoning-glyph rings: two thin rotating circles standing in for her Schnee glyphs. */
.weissGlyphRing1 {
  position: absolute;
  left: 8%;
  top: 22%;
  width: 220px;
  height: 220px;
  border-radius: 50%;
  border: 1.5px solid color-mix(in srgb, var(--iceHot) 55%, transparent);
  box-shadow: 0 0 24px color-mix(in srgb, var(--iceHot) 40%, transparent) inset, 0 0 30px color-mix(in srgb, var(--iceHot) 25%, transparent);
  opacity: .3;
  z-index: 2;
  animation: weissSpin 26s linear infinite, weissGlyphPulse 6s ease-in-out infinite;
}

.weissGlyphRing2 {
  position: absolute;
  right: 18%;
  bottom: 14%;
  width: 130px;
  height: 130px;
  border-radius: 50%;
  border: 1px solid color-mix(in srgb, var(--iceCore) 60%, transparent);
  box-shadow: 0 0 16px color-mix(in srgb, var(--iceHot) 35%, transparent) inset;
  opacity: .26;
  z-index: 2;
  animation: weissSpinReverse 20s linear infinite, weissGlyphPulse 7.5s ease-in-out infinite;
}

/* Near shimmer: bright ice-dust close to camera. */
.weissShimmer {
  position: absolute;
  inset: -50% 0 0 0;
  z-index: 3;
  background-image:
    radial-gradient(2px 2px at 20% 30%, var(--iceCore), transparent 60%),
    radial-gradient(2.5px 2.5px at 70% 10%, var(--iceHot), transparent 60%),
    radial-gradient(1.5px 1.5px at 45% 75%, var(--iceCore), transparent 60%),
    radial-gradient(2.5px 2.5px at 90% 55%, var(--iceHot), transparent 60%),
    radial-gradient(1.5px 1.5px at 8% 62%, var(--iceCore), transparent 60%);
  background-size: 180px 240px, 260px 320px, 220px 280px, 300px 380px, 240px 300px;
  filter: drop-shadow(0 0 6px color-mix(in srgb, var(--iceHot) 60%, transparent));
  opacity: .85;
  animation: weissDriftNear 20s linear infinite, weissTwinkle 4.5s ease-in-out infinite;
  mask-image: linear-gradient(to top, #000 20%, transparent 85%);
}

/* Far shimmer: dimmer, slower dust. */
.weissShimmerFar {
  position: absolute;
  inset: -50% 0 0 0;
  z-index: 3;
  background-image:
    radial-gradient(1px 1px at 35% 20%, var(--iceHot), transparent 60%),
    radial-gradient(1.5px 1.5px at 80% 65%, var(--iceCore), transparent 60%),
    radial-gradient(1px 1px at 55% 45%, var(--iceHot), transparent 60%),
    radial-gradient(1.5px 1.5px at 12% 85%, var(--iceCore), transparent 60%);
  background-size: 140px 190px, 200px 250px, 170px 210px, 230px 290px;
  filter: drop-shadow(0 0 3px color-mix(in srgb, var(--iceCore) 50%, transparent));
  opacity: .4;
  animation: weissDriftFar 40s linear infinite;
  mask-image: linear-gradient(to top, #000 15%, transparent 75%);
}

@keyframes weissSway {
  0%, 100% { transform: translateY(0) rotate(0deg) scale(1); opacity: .36; }
  35%      { transform: translateY(-4px) rotate(-.3deg) scale(1.003); opacity: .41; }
  70%      { transform: translateY(2px) rotate(.25deg) scale(.999); opacity: .34; }
}

@keyframes weissSpin {
  to { transform: rotate(360deg); }
}

@keyframes weissSpinReverse {
  to { transform: rotate(-360deg); }
}

@keyframes weissGlyphPulse {
  0%, 100% { opacity: .3; }
  50%      { opacity: .14; }
}

@keyframes weissDriftNear {
  to { background-position: 20px -260px, -30px -340px, 24px -300px, -18px -400px, 26px -320px; }
}

@keyframes weissDriftFar {
  to { background-position: -16px -200px, 22px -260px, -24px -220px, 16px -300px; }
}

@keyframes weissTwinkle {
  0%, 100% { opacity: .85; }
  50%      { opacity: .55; }
}

@media (prefers-reduced-motion: reduce) {
  .weissChar, .weissShimmer, .weissShimmerFar, .weissGlyphRing1, .weissGlyphRing2 { animation: none; }
}

write.css:
.pageBackground {
  --shadowHot: #8a63ff;
  --shadowCore: #d8c9ff;
  --shadowMid: #2a1a45;
  --shadowDeep: #05030a;
  overflow: hidden;
}

.blakeScene {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(120% 80% at 50% 118%, color-mix(in srgb, var(--shadowMid) 55%, transparent) 0%, transparent 62%),
    linear-gradient(to top, color-mix(in srgb, var(--shadowDeep) 82%, transparent) 0%, transparent 58%);
}

.blakeGlow {
  position: absolute;
  inset: auto -10% -30% -10%;
  height: 70%;
  background: radial-gradient(60% 100% at 50% 100%, color-mix(in srgb, var(--shadowHot) 22%, transparent) 0%, color-mix(in srgb, var(--shadowMid) 22%, transparent) 45%, transparent 75%);
  filter: blur(34px);
  opacity: .55;
}

.blakeFloor {
  position: absolute;
  inset: auto 0 0 0;
  height: 14%;
  background: linear-gradient(to top, color-mix(in srgb, var(--shadowMid) 45%, transparent), transparent);
  filter: blur(10px);
}

/* The clone: a second copy of the same render, offset and dimmer, drifting out of sync with the
   real one, looks like an afterimage her Semblance leaves behind rather than a second character. */
.blakeChar {
  position: absolute;
  right: 0%;
  bottom: 12px;
  width: auto;
  height: 102%;
  object-fit: contain;
  object-position: bottom right;
  opacity: .36;
  filter: drop-shadow(0 0 36px color-mix(in srgb, var(--shadowHot) 30%, transparent));
  mask-image: linear-gradient(to top, transparent 0%, #000 14%, #000 100%);
  z-index: 2;
  transform-origin: 60% 100%;
  animation: blakeWaver 16s ease-in-out infinite;
}

.blakeCharShadow {
  position: absolute;
  right: 4%;
  bottom: 10px;
  width: auto;
  height: 100%;
  object-fit: contain;
  object-position: bottom right;
  opacity: .16;
  filter: blur(1.5px) brightness(0) saturate(100%) sepia(1) hue-rotate(220deg) drop-shadow(0 0 20px color-mix(in srgb, var(--shadowHot) 40%, transparent));
  mask-image: linear-gradient(to top, transparent 0%, #000 14%, #000 100%);
  z-index: 1;
  transform-origin: 60% 100%;
  animation: blakeDrift 9s ease-in-out infinite;
}

/* Near wisps: short violet ribbons instead of dots, tumbling like a clone dissolving. */
.blakeWisps {
  position: absolute;
  inset: -50% 0 0 0;
  z-index: 3;
  background-image:
    radial-gradient(10px 2px at 20% 30%, color-mix(in srgb, var(--shadowHot) 70%, transparent), transparent 70%),
    radial-gradient(14px 2px at 70% 10%, color-mix(in srgb, var(--shadowCore) 70%, transparent), transparent 70%),
    radial-gradient(8px 1.5px at 45% 75%, color-mix(in srgb, var(--shadowHot) 70%, transparent), transparent 70%),
    radial-gradient(12px 2px at 90% 55%, color-mix(in srgb, var(--shadowHot) 70%, transparent), transparent 70%),
    radial-gradient(9px 1.5px at 8% 62%, color-mix(in srgb, var(--shadowCore) 70%, transparent), transparent 70%);
  background-size: 200px 260px, 280px 340px, 240px 300px, 320px 400px, 260px 320px;
  filter: drop-shadow(0 0 6px color-mix(in srgb, var(--shadowHot) 55%, transparent));
  opacity: .55;
  animation: blakeDriftNear 24s linear infinite, blakePulseNear 5.5s ease-in-out infinite;
  mask-image: linear-gradient(to top, #000 20%, transparent 85%);
}

/* Far wisps: fainter, slower. */
.blakeWispsFar {
  position: absolute;
  inset: -50% 0 0 0;
  z-index: 3;
  background-image:
    radial-gradient(7px 1.5px at 35% 20%, color-mix(in srgb, var(--shadowHot) 60%, transparent), transparent 70%),
    radial-gradient(9px 1.5px at 80% 65%, color-mix(in srgb, var(--shadowCore) 60%, transparent), transparent 70%),
    radial-gradient(6px 1px at 55% 45%, color-mix(in srgb, var(--shadowHot) 60%, transparent), transparent 70%),
    radial-gradient(8px 1.5px at 12% 85%, color-mix(in srgb, var(--shadowCore) 60%, transparent), transparent 70%);
  background-size: 160px 210px, 220px 270px, 190px 230px, 250px 310px;
  filter: drop-shadow(0 0 3px color-mix(in srgb, var(--shadowCore) 45%, transparent));
  opacity: .3;
  animation: blakeDriftFar 44s linear infinite;
  mask-image: linear-gradient(to top, #000 15%, transparent 75%);
}

@keyframes blakeWaver {
  0%, 100% { transform: translateY(0) rotate(0deg) scale(1); opacity: .36; }
  35%      { transform: translateY(-4px) rotate(.3deg) scale(1.003); opacity: .41; }
  70%      { transform: translateY(2px) rotate(-.2deg) scale(.999); opacity: .34; }
}

@keyframes blakeDrift {
  0%, 100% { transform: translate(0, 0); opacity: .16; }
  50%      { transform: translate(10px, -6px); opacity: .08; }
}

@keyframes blakeDriftNear {
  to { background-position: 24px -280px, -34px -360px, 28px -320px, -20px -420px, 30px -340px; }
}

@keyframes blakeDriftFar {
  to { background-position: -18px -210px, 26px -280px, -28px -240px, 18px -320px; }
}

@keyframes blakePulseNear {
  0%, 100% { opacity: .55; }
  50%      { opacity: .32; }
}

@media (prefers-reduced-motion: reduce) {
  .blakeChar, .blakeCharShadow, .blakeWisps, .blakeWispsFar { animation: none; }
}

prompts.css:
.pageBackground {
  --emberHot: #ffb020;
  --emberCore: #fff3d0;
  --emberMid: #c8590a;
  --emberDeep: #2a0f04;
  overflow: hidden;
}

.yangScene {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(58% 80% at 62% -8%, color-mix(in srgb, var(--emberCore) 40%, transparent) 0%, color-mix(in srgb, var(--emberHot) 18%, transparent) 40%, transparent 72%),
    radial-gradient(120% 90% at 62% -18%, color-mix(in srgb, var(--emberHot) 50%, transparent) 0%, transparent 64%),
    linear-gradient(to bottom, color-mix(in srgb, var(--emberMid) 26%, transparent) 0%, transparent 45%),
    linear-gradient(to top, color-mix(in srgb, var(--emberHot) 16%, transparent) 0%, color-mix(in srgb, var(--emberDeep) 40%, transparent) 20%, transparent 55%);
}

.yangChar {
  position: absolute;
  right: 0;
  bottom: 12px;
  height: 100%;
  object-fit: contain;
  object-position: bottom right;
  opacity: .38;
  mask-image: linear-gradient(to top, transparent 0%, #000 14%, #000 100%);
  z-index: 1;
  transform-origin: 60% 100%;
  will-change: transform, opacity;
  animation: yangWaver 13s ease-in-out infinite;
}

/* Rising embers instead of falling ones: she is the one on fire, so the sparks climb. */
.yangEmbers {
  position: absolute;
  inset: -50% 0 -20% 0;
  z-index: 3;
  background-image:
    radial-gradient(2px 2px at 20% 30%, var(--emberCore), transparent 60%),
    radial-gradient(3px 3px at 70% 10%, var(--emberCore), transparent 60%),
    radial-gradient(2px 2px at 45% 75%, var(--emberHot), transparent 60%),
    radial-gradient(3px 3px at 90% 55%, var(--emberCore), transparent 60%),
    radial-gradient(2px 2px at 8% 62%, var(--emberHot), transparent 60%);
  background-size: 180px 240px, 260px 320px, 220px 280px, 300px 380px, 240px 300px;
  filter: drop-shadow(0 0 7px var(--emberHot));
  opacity: .9;
  animation: yangRiseNear 12s linear infinite, yangFlicker 2.4s ease-in-out infinite;
  mask-image: linear-gradient(to bottom, #000 20%, transparent 85%);
}

.yangEmbersFar {
  position: absolute;
  inset: -50% 0 -20% 0;
  z-index: 3;
  background-image:
    radial-gradient(1.5px 1.5px at 35% 20%, var(--emberHot), transparent 60%),
    radial-gradient(1.5px 1.5px at 80% 65%, var(--emberCore), transparent 60%),
    radial-gradient(1px 1px at 55% 45%, var(--emberHot), transparent 60%),
    radial-gradient(1.5px 1.5px at 12% 85%, var(--emberHot), transparent 60%);
  background-size: 140px 190px, 200px 250px, 170px 210px, 230px 290px;
  filter: drop-shadow(0 0 4px var(--emberHot));
  opacity: .5;
  animation: yangRiseFar 22s linear infinite;
  mask-image: linear-gradient(to bottom, #000 15%, transparent 75%);
}

@keyframes yangWaver {
  0%, 100% { transform: translateY(0) rotate(0deg); opacity: .38; }
  35%      { transform: translateY(-5px) rotate(.3deg); opacity: .46; }
  70%      { transform: translateY(3px) rotate(-.2deg); opacity: .34; }
}

@keyframes yangRiseNear {
  to { background-position: 12px -340px, -22px -420px, 16px -380px, -12px -480px, 20px -400px; }
}

@keyframes yangRiseFar {
  to { background-position: -8px -290px, 10px -350px, -14px -310px, 6px -390px; }
}

@keyframes yangFlicker {
  0%, 100% { opacity: .9; }
  50%      { opacity: .6; }
}

@media (prefers-reduced-motion: reduce) {
  .yangChar, .yangEmbers, .yangEmbersFar { animation: none; }
}
